// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(address(c).balance >= amount);
        vm.deal(address(c), amount);
        uint256 balanceBefore = receiver.balance;
        c.sendTo(receiver, amount);
        uint256 balanceAfter = receiver.balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
